/**
 * Re-admits a former member on the same row. Role, inviter and join date come
 * from the invitation that brought them back; everything else recorded on the
 * membership stays attached.
 */
export async function reinstateMember(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
  invitedBy: UserId | null,
  joinedAt: IsoTimestamp,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
      ...restorePatch(),
      role,
      status: "active",
      invitedBy,
      joinedAt,
    })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

