export async function listDigestRecipients(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  return preferenceRepo.listDigestSubscribers(orgId);
}

input.new_string:
export async function listDigestRecipients(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  const subscribers = await preferenceRepo.listDigestSubscribers(orgId);
  const current: UserId[] = [];
  for (const userId of subscribers) {
    const membership = await memberRepo.findMember(orgId, userId);
    if (isCurrentMember(membership)) current.push(userId);
  }
  return current;
}

